'use strict';
const test=require('node:test');
const assert=require('node:assert/strict');
const api=require('../lab-engine.js');
function setup(options={}){
 assert.equal(typeof api.createLab,'function','实验模型接口尚未实现');
 let time=0;const base=Date.parse('2026-10-14T00:00:00.000Z');
 const lab=api.createLab({settleSec:1,windowSamples:3,clock:()=>base+time*1000,monotonic:()=>time,...options});
 return {lab,at(t){time=t;lab.tick();},now(t){time=t;}};
}
function baseline(ctx){ctx.lab.setConfirmations({stopped:true,positioned:true,oriented:true});ctx.lab.requestBaseline();ctx.at(1);ctx.at(2);ctx.at(3);assert.equal(ctx.lab.snapshot().baselineReady,true);}
function heat(ctx){ctx.lab.startRunning();ctx.at(12);ctx.lab.returnToPoint();ctx.lab.setConfirmations({stopped:true,positioned:true,oriented:true});ctx.lab.requestMeasurement();ctx.at(13);ctx.at(14);ctx.at(15);}

test('初始化为明确的模拟模式，未建立基准时没有XYZ或RMS',()=>{const c=setup();const s=c.lab.snapshot();assert.equal(s.mode,'simulation');assert.equal(s.phase,'IDLE');assert.equal(s.lastXYZ,null);assert.equal(s.rmsUm,null);assert.equal(s.temperatureNames.length,18);});
test('未建立基准不能启动运行；缺少任何复位确认不能建立基准',()=>{const c=setup();assert.throws(()=>c.lab.startRunning(),/基准/);c.lab.setConfirmations({stopped:true,positioned:true,oriented:false});assert.throws(()=>c.lab.requestBaseline(),/确认/);assert.equal(c.lab.snapshot().baselineReady,false);});
test('等待结束后才收集窗口，达到规定点数才建立一次基准',()=>{const c=setup();c.lab.setConfirmations({stopped:true,positioned:true,oriented:true});c.lab.requestBaseline();c.at(.5);assert.equal(c.lab.snapshot().windowCount,0);c.at(1);assert.equal(c.lab.snapshot().windowCount,1);c.at(2);c.at(3);const old=c.lab.snapshot().baseline.slice();assert.throws(()=>c.lab.requestBaseline(),/一次|基准/);assert.deepEqual(c.lab.snapshot().baseline,old);});
test('有效热窗口得到XYZ，基准仍保持原值，实际与模拟时间分别保存',()=>{const c=setup();baseline(c);const zero=c.lab.snapshot().baseline.slice();heat(c);const w=c.lab.snapshot().windows.filter(w=>w.kind==='thermal'&&w.valid);assert.equal(w.length,1);assert.ok(w[0].xyz.every(Number.isFinite));assert.ok(Math.abs(w[0].xyz[0])>1);assert.deepEqual(c.lab.snapshot().baseline,zero);const r=c.lab.snapshot().raw.at(-1);assert.equal(r.mode,'simulation');assert.equal(r.elapsedWallSec,15);assert.ok(r.simulationTimeSec>r.elapsedWallSec);assert.equal(r.actualTimeIso,'2026-10-14T00:00:15.000Z');});
test('活跃实验冷却组合冻结，两个支路按区域成对启用',()=>{const c=setup();c.lab.setGroup('AC');baseline(c);assert.throws(()=>c.lab.setGroup('B'),/冻结|新建/);c.lab.startRunning();c.at(4);assert.deepEqual(c.lab.snapshot().command,[60,60,0,0,60,60]);});
test('运行状态原始超程记录保留，但不产生有效XYZ',()=>{const c=setup();baseline(c);c.lab.startRunning();c.at(4);assert.equal(c.lab.snapshot().lastXYZ,null);assert.ok(c.lab.snapshot().raw.at(-1).probes.some(p=>Math.abs(p)>100));assert.equal(c.lab.snapshot().windows.filter(w=>w.kind==='thermal'&&w.valid).length,0);});
test('采样中失去定位确认使窗口无效，并保留POSE_CHANGED原因',()=>{const c=setup();baseline(c);c.lab.startRunning();c.at(8);c.lab.returnToPoint();c.lab.setConfirmations({stopped:true,positioned:true,oriented:true});c.lab.requestMeasurement();c.at(9);c.lab.setConfirmations({stopped:true,positioned:false,oriented:true});c.at(10);const w=c.lab.snapshot().windows.at(-1);assert.equal(w.valid,false);assert.equal(w.reason,'POSE_CHANGED');assert.equal(c.lab.snapshot().lastXYZ,null);});
test('窗口中的单点超程不能由均值掩盖',()=>{const c=setup();baseline(c);c.lab.startRunning();c.at(8);c.lab.returnToPoint();c.lab.setConfirmations({stopped:true,positioned:true,oriented:true});c.lab.requestMeasurement();c.lab.inject('overrange');c.at(9);const w=c.lab.snapshot().windows.at(-1);assert.equal(w.valid,false);assert.equal(w.reason,'OUT_OF_RANGE');assert.equal(c.lab.snapshot().lastXYZ,null);});
test('通信失败记录缺失值，恢复保留基准但清除位置确认',()=>{const c=setup();baseline(c);const zero=c.lab.snapshot().baseline.slice();c.lab.startRunning();c.lab.inject('communication');c.at(6);assert.equal(c.lab.snapshot().phase,'FAULT');const raw=c.lab.snapshot().raw.at(-1);assert.equal(raw.quality,'COMMUNICATION_ERROR');assert.ok(raw.probes.every(Number.isNaN));c.lab.recover();const s=c.lab.snapshot();assert.deepEqual(s.baseline,zero);assert.deepEqual(s.confirmations,{stopped:false,positioned:false,oriented:false});assert.equal(s.phase,'READY');});
test('终止不完整窗口保留CANCELLED记录',()=>{const c=setup();baseline(c);c.lab.startRunning();c.at(8);c.lab.returnToPoint();c.lab.setConfirmations({stopped:true,positioned:true,oriented:true});c.lab.requestMeasurement();c.at(9);c.lab.stop();assert.equal(c.lab.snapshot().windows.at(-1).reason,'CANCELLED');assert.equal(c.lab.snapshot().phase,'FINISHED');});
test('FIFO通信队列的重入请求仍在当前任务结束后执行',()=>{assert.equal(typeof api.createQueue,'function','统一队列接口尚未实现');const q=api.createQueue();const order=[];q.push('first',()=>{order.push('first-start');q.push('nested',()=>order.push('nested'));q.flush();order.push('first-end');});q.push('second',()=>order.push('second'));q.flush();assert.deepEqual(order,['first-start','first-end','second','nested']);assert.equal(q.maxConcurrent,1);});
test('导出保留原始、窗口、事件和模拟标记，空窗口不伪造热位移',()=>{const c=setup();const empty=c.lab.exportData();assert.ok(empty.windowsCsv.startsWith('experiment_id'));assert.equal(empty.windowsCsv.trim().split('\n').length,1);baseline(c);heat(c);const files=c.lab.exportData();const meta=JSON.parse(files.metadataJson);assert.equal(meta.mode,'simulation');assert.match(meta.calibrationSource,/模拟/);assert.ok(files.rawCsv.includes('actual_time_iso'));assert.ok(files.rawCsv.includes('simulation_time_s'));assert.ok(files.rawCsv.includes('simulation'));assert.ok(files.windowsCsv.includes('thermal'));assert.ok(files.eventsCsv.includes('BASELINE_COMPLETE'));});
test('拒绝真实模式和倒退的单调时钟',()=>{assert.equal(typeof api.createLab,'function');assert.throws(()=>api.createLab({mode:'real'}),/模拟|真实/);const c=setup();c.at(2);assert.throws(()=>c.at(1),/时间|时钟/);});
test('位移正负号为C乘以基准减当前，与MATLAB相同',()=>{const c=setup();baseline(c);c.lab.returnToPoint();c.lab.setConfirmations({stopped:true,positioned:true,oriented:true});c.lab.requestMeasurement();const zero=c.lab.snapshot().baseline;c.lab.simulate=()=>({temps:Array(18).fill(20),probes:zero.map((v,i)=>v-(i+1)),flow:Array(6).fill(0),waterIn:Array(6).fill(20),waterOut:Array(6).fill(20)});c.at(4);c.at(5);c.at(6);const expected=api.DEMO_C.map(row=>row.reduce((s,v,i)=>s+v*(i+1),0));const actual=c.lab.snapshot().lastXYZ;actual.forEach((v,i)=>assert.ok(Math.abs(v-expected[i])<1e-9));});
test('加速热模型仅累计运行时长，包括两次采样之间的运行结束',()=>{const c=setup();baseline(c);c.now(20);c.lab.startRunning();c.at(21);assert.equal(c.lab.snapshot().simulationTimeSec,120);c.now(21.5);c.lab.returnToPoint();c.at(22);assert.equal(c.lab.snapshot().simulationTimeSec,180);});
test('不能用冷态基准旧确认直接请求热窗口',()=>{const c=setup();baseline(c);assert.throws(()=>c.lab.requestMeasurement(),/返回/);c.lab.returnToPoint();assert.throws(()=>c.lab.requestMeasurement(),/确认/);});
test('稳定等待中出现超程也必须否决该窗口',()=>{const c=setup({settleSec:2});c.lab.setConfirmations({stopped:true,positioned:true,oriented:true});c.lab.requestBaseline();c.lab.inject('overrange');c.at(1);assert.equal(c.lab.snapshot().windows.at(-1).reason,'OUT_OF_RANGE');assert.equal(c.lab.snapshot().baselineReady,false);});
test('非有限温度不得作为质量正常记录或有效窗口',()=>{const c=setup();c.lab.setConfirmations({stopped:true,positioned:true,oriented:true});c.lab.requestBaseline();const normal=c.lab.simulate.bind(c.lab);c.lab.simulate=()=>{const row=normal();row.temps[0]=NaN;return row;};c.at(1);const s=c.lab.snapshot();assert.equal(s.raw.at(-1).quality,'NONFINITE');assert.equal(s.windows.at(-1).reason,'NONFINITE');assert.equal(s.baselineReady,false);});
